#include "../src/Ast.h"
#include <iostream>
#include <unordered_map>
int main(){std::unordered_map<std::string,json::Document> vars{{"x",json::Document(7.0)},{"y",json::Document(3.0)}};nift::ast::Context c;c.resolve=[&](const std::string&n,json::Document&o,std::string&e){auto i=vars.find(n);if(i==vars.end()){e="missing "+n;return false;}o=i->second;return true;};c.render=[](const json::Document&d){return d.is_string()?d.string:(d.is_number()?std::to_string(d.num):std::string());};for(auto q:{"42","x","(x + y) * 2","x + y * 2","-x + 10","x > y && y == 3","x < y || y <= 3","!(x < y)"}){auto p=nift::ast::parse_expression(q);if(!p.supported){std::cerr<<q<<": "<<p.error<<"\n";return 1;}json::Document o;std::string e;if(!nift::ast::evaluate(*p.expr,c,o,e)){std::cerr<<e<<"\n";return 1;}}return 0;}
